# ---- writer + self-verification (exact id list only, no glob) ----
BATCHES = json.loads((ROOT / 'batches.json').read_text(encoding='utf-8'))
MY_IDS = BATCHES['B23'] + BATCHES['B24'] + BATCHES['B25']
assert len(MY_IDS) == 47, len(MY_IDS)
assert set(P.keys()) == set(MY_IDS), (set(MY_IDS) - set(P.keys()), set(P.keys()) - set(MY_IDS))

written = []
for cid in MY_IDS:
    d = P[cid]
    obj = {
        'case_id': cid,
        'prediction_text': d['prediction_text'],
        'basis': d['basis'],
        'confidence': d['conf'],
        'trigger': d['trig'],
    }
    fp = PRED / (cid + '.json')
    fp.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding='utf-8')
    written.append(fp)

cm = ru = di = 0
for cid in MY_IDS:
    fp = PRED / (cid + '.json')
    obj = json.loads(fp.read_text(encoding='utf-8'))
    assert obj['case_id'] == cid
    assert set(obj.keys()) == {'case_id', 'prediction_text', 'basis', 'confidence', 'trigger'}, obj.keys()
    t = obj['trigger']
    assert set(t.keys()) == {'changed_main', 'reserve_used', 'disputed', 'reason'}
    cm += bool(t['changed_main']); ru += bool(t['reserve_used']); di += bool(t['disputed'])
    print(cid, fp.stat().st_size)
print('TOTAL', len(written), 'changed_main', cm, 'reserve_used', ru, 'disputed', di)
